const errors = [];

if (!body.dataset_session_id) {
  errors.push('Missing dataset_session_id.');
}

if (!keys.length) {
  errors.push('No dataset files were received.');
}

const allowedExt = new Set(['csv', 'xlsx']);
const maxFileBytes = 20 * 1024 * 1024; // 20MB per file
const maxFiles = 10;

if (keys.length > maxFiles) {
  errors.push(`Too many files: ${keys.length}. Maximum allowed is ${maxFiles}.`);
}

for (const key of keys) {
  const b = binary[key];
  const name = b.fileName || key;
  const ext = name.toLowerCase().split('.').pop();

  if (!allowedExt.has(ext)) {
    errors.push(`Unsupported file type: ${name} (.${ext}).`);
    continue;
  }

  const size = Number(b.fileSize || 0);
  if (size && size > maxFileBytes) {
    errors.push(`File too large: ${name} (${(size / 1024 / 1024).toFixed(1)}MB). Limit is 20MB.`);
  }
}

if (errors.length) {
  throw new Error(`Dataset upload validation failed: ${errors.join(' ')}`);
}

// Validation passed -- pass the original item through unchanged (binary preserved).
return [item];

