import io
import pandas as pd

item = _items[0]
payload = item['json']

profiles = []
for file_info in payload['files']:
    raw = base64.b64decode(file_info['data_base64'])
    ext = file_info['extension']
    name = file_info['file_name']

    if ext == 'csv':
        try:
            df = pd.read_csv(io.BytesIO(raw))
        except UnicodeDecodeError:
            df = pd.read_csv(io.BytesIO(raw), encoding='latin-1')
    elif ext == 'xlsx':
        df = pd.read_excel(io.BytesIO(raw), engine='openpyxl')
    else:
        raise ValueError(f'Unsupported extension: {ext}')

    columns = []
    for col in df.columns:
        series = df[col]
        columns.append({
            'name': str(col),
            'dtype': str(series.dtype),
            'null_count': int(series.isna().sum()),
            'null_rate': round(float(series.isna().mean()), 6),
            'unique_count': int(series.nunique(dropna=True)),
            'sample_values': [str(x) for x in series.dropna().head(5).tolist()]
        })

    profiles.append({
        'file_name': name,
        'extension': ext,
        'rows': int(len(df)),
        'columns': int(len(df.columns)),
        'duplicate_rows': int(df.duplicated().sum()),
        'column_names': [str(c) for c in df.columns],
        'columns_detail': columns,
        'preview': [
            {str(k): (None if pd.isna(v) else str(v)) for k, v in row.items()}
            for row in df.head(3).to_dict(orient='records')
        ]
    })

return [{
    'json': {
        'dataset_session_id': payload['dataset_session_id'],
        'app_session_id': payload.get('app_session_id'),
        'file_count': len(profiles),
        'profiles': profiles
    }
}]

