const raw = $input.item.json.output ?? '';
let plan;

if (raw && typeof raw === 'object') {
  plan = raw;
} else if (typeof raw === 'string') {
  try {
    plan = JSON.parse(raw);
  } catch (e) {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start < 0 || end < start) {
      throw new Error('AI planner did not return valid JSON');
    }
    plan = JSON.parse(raw.slice(start, end + 1));
  }
} else {
  throw new Error('Unexpected AI planner output');
}

const profileItem = $('Python — Profile Raw Dataset').item;
const profiles = profileItem.json.profiles;
const sessionId = profileItem.json.dataset_session_id;
const appSessionId = profileItem.json.app_session_id;
// Carried forward so every downstream Python node gets everything it needs
// from its own direct input -- no cross-node lookups required past this point.
const files = $('Bridge Binary Files').item.json.files;

// Hard reliability rule: one file is ALWAYS standalone.
if (profiles.length === 1) {
  plan.decision = 'standalone';
  plan.operations = [];
  plan.reason = plan.reason || 'Only one dataset file was supplied.';
}

// Defensive default: if the model omitted file_plans, fall back to
// treating every column as text so cleaning becomes a safe no-op
// instead of crashing the pipeline.
if (!Array.isArray(plan.file_plans) || !plan.file_plans.length) {
  plan.file_plans = profiles.map(p => ({
    file_name: p.file_name,
    columns: p.column_names.map(name => ({ name, role: 'text', needs_trim: false, needs_case_normalize: false }))
  }));
}

return [{
  json: {
    dataset_session_id: sessionId,
    app_session_id: appSessionId,
    profiles,
    plan,
    files
  }
}];

