import base64
import io
import re
import pandas as pd

item = _items[0]
payload = item['json']
files = payload['files']
file_plans = {fp['file_name']: fp for fp in payload['plan'].get('file_plans', [])}

BOOL_TRUE = {'true', 'yes', 'y', '1'}
BOOL_FALSE = {'false', 'no', 'n', '0'}

def strip_currency(series):
    cleaned = series.astype(str).str.replace(r'[₦$€£,\s]', '', regex=True)
    cleaned = cleaned.replace({'': None, 'nan': None, 'None': None})
    return pd.to_numeric(cleaned, errors='coerce')

def strip_percent(series):
    cleaned = series.astype(str).str.replace('%', '', regex=False).str.replace(',', '', regex=False).str.strip()
    cleaned = cleaned.replace({'': None, 'nan': None, 'None': None})
    return pd.to_numeric(cleaned, errors='coerce')

def map_boolean(series):
    def convert(v):
        if pd.isna(v):
            return None
        s = str(v).strip().lower()
        if s in BOOL_TRUE:
            return True
        if s in BOOL_FALSE:
            return False
        return None
    return series.apply(convert)

def normalize_category(series):
    cleaned = series.astype(str).str.strip()
    cleaned = cleaned.str.replace(r'\s+', ' ', regex=True)
    cleaned = cleaned.str.title()
    cleaned = cleaned.replace({'Nan': None, '': None})
    return cleaned

cleaned_datasets = []
overall_warnings = []
overall_stats = {
    'missing_values': 0,
    'duplicate_rows': 0,
    'columns_converted': 0,
    'categories_standardized': 0,
    'invalid_values': 0,
    'rows_removed': 0
}

for file_info in files:
    raw = base64.b64decode(file_info['data_base64'])
    ext = file_info['extension']
    name = file_info['file_name']

    if ext == 'csv':
        try:
            df = pd.read_csv(io.BytesIO(raw))
        except UnicodeDecodeError:
            df = pd.read_csv(io.BytesIO(raw), encoding='latin-1')
    elif ext == 'xlsx':
        df = pd.read_excel(io.BytesIO(raw), engine='openpyxl')
    else:
        raise ValueError(f'Unsupported extension: {ext}')

    original_rows = int(len(df))

    # 1. Column names: trim whitespace, collapse internal whitespace.
    df.columns = [re.sub(r'\s+', ' ', str(c)).strip() for c in df.columns]

    # 2. Drop columns that are entirely empty -- safe, information-free.
    empty_cols = [c for c in df.columns if df[c].isna().all()]
    if empty_cols:
        df = df.drop(columns=empty_cols)

    # 3. Flag (do NOT drop) constant columns -- could be a legitimate
    #    single-value field (e.g. every row is "Nigeria").
    constant_cols = [c for c in df.columns if df[c].nunique(dropna=True) == 1]

    plan = file_plans.get(name, {'columns': []})
    role_by_col = {c['name']: c for c in plan.get('columns', [])}

    columns_converted = 0
    categories_standardized = 0
    invalid_values = 0

    for col in df.columns:
        role_info = role_by_col.get(col, {})
        role = role_info.get('role', 'text')

        if role == 'currency':
            before_na = int(df[col].isna().sum())
            df[col] = strip_currency(df[col])
            after_na = int(df[col].isna().sum())
            invalid_values += max(0, after_na - before_na)
            columns_converted += 1
        elif role == 'percent':
            before_na = int(df[col].isna().sum())
            df[col] = strip_percent(df[col])
            after_na = int(df[col].isna().sum())
            invalid_values += max(0, after_na - before_na)
            columns_converted += 1
        elif role == 'number':
            before_na = int(df[col].isna().sum())
            df[col] = pd.to_numeric(
                df[col].astype(str).str.replace(',', '', regex=False),
                errors='coerce'
            )
            after_na = int(df[col].isna().sum())
            invalid_values += max(0, after_na - before_na)
            columns_converted += 1
        elif role == 'date':
            before_na = int(df[col].isna().sum())
            df[col] = pd.to_datetime(df[col], errors='coerce')
            after_na = int(df[col].isna().sum())
            invalid_values += max(0, after_na - before_na)
            columns_converted += 1
        elif role == 'boolean':
            df[col] = map_boolean(df[col])
            columns_converted += 1
        elif role == 'category':
            before_unique = int(df[col].nunique(dropna=True))
            df[col] = normalize_category(df[col])
            after_unique = int(df[col].nunique(dropna=True))
            if after_unique < before_unique:
                categories_standardized += 1
        # 'identifier' and 'text' roles are left untouched -- trimming an ID
        # or free-text field risks changing its meaning.

    # 4. Duplicate rows: exact full-row duplicates are safe to drop.
    dup_count = int(df.duplicated().sum())
    df = df.drop_duplicates()
    rows_removed = original_rows - int(len(df))

    # 5. Missing values: count only -- never impute automatically.
    missing_total = int(df.isna().sum().sum())

    # 6. Outlier flagging (IQR method) -- flag only, never remove.
    outlier_warnings = []
    for col in df.columns:
        if role_by_col.get(col, {}).get('role') in ('number', 'currency', 'percent'):
            series = df[col].dropna()
            if len(series) >= 10:
                q1 = series.quantile(0.25)
                q3 = series.quantile(0.75)
                iqr = q3 - q1
                if iqr > 0:
                    lower = q1 - 1.5 * iqr
                    upper = q3 + 1.5 * iqr
                    outlier_count = int(((series < lower) | (series > upper)).sum())
                    if outlier_count > 0:
                        rate = round(outlier_count / len(series) * 100, 1)
                        if rate >= 1:
                            outlier_warnings.append(
                                f"{name}: '{col}' has {outlier_count} possible outliers ({rate}% of values)."
                            )

    file_warnings = list(outlier_warnings)
    if constant_cols:
        file_warnings.append(f"{name}: constant column(s) kept but flagged: {', '.join(constant_cols)}.")
    if empty_cols:
        file_warnings.append(f"{name}: dropped fully empty column(s): {', '.join(empty_cols)}.")
    if dup_count:
        file_warnings.append(f"{name}: removed {dup_count} exact duplicate row(s).")

    for col in df.columns:
        null_rate = float(df[col].isna().mean())
        if null_rate >= 0.01:
            file_warnings.append(f"{name}: '{col}' contains {round(null_rate * 100, 1)}% missing values.")

    records = df.to_dict(orient='records')
    for row in records:
        for key, value in list(row.items()):
            if pd.isna(value):
                row[key] = None
            else:
                try:
                    row[key] = value.isoformat()
                except AttributeError:
                    row[key] = str(value) if not isinstance(value, (int, float, bool)) else value

    cleaned_datasets.append({
        'file_name': name,
        'rows': int(len(df)),
        'columns': list(df.columns),
        'role_map': {c: role_by_col.get(c, {}).get('role', 'text') for c in df.columns},
        'records': records
    })

    overall_stats['missing_values'] += missing_total
    overall_stats['duplicate_rows'] += dup_count
    overall_stats['columns_converted'] += columns_converted
    overall_stats['categories_standardized'] += categories_standardized
    overall_stats['invalid_values'] += invalid_values
    overall_stats['rows_removed'] += rows_removed
    overall_warnings.extend(file_warnings)

return [{
    'json': {
        'dataset_session_id': payload['dataset_session_id'],
        'app_session_id': payload.get('app_session_id'),
        'plan': payload['plan'],
        'cleaned_datasets': cleaned_datasets,
        'quality_stats': overall_stats,
        'quality_warnings': overall_warnings
    }
}]

import pandas as pd

item = _items[0]
payload = item['json']
plan = payload['plan']
decision = plan.get('decision', 'standalone')
cleaned_datasets = payload['cleaned_datasets']
by_name = {d['file_name']: d for d in cleaned_datasets}

validation_warnings = []

if decision == 'reject':
    raise ValueError(f"Dataset planner rejected this upload: {plan.get('reason', 'no reason given')}")

if decision == 'standalone':
    pass  # nothing to validate -- single dataset flows through untouched

elif decision in ('append', 'join'):
    operations = plan.get('operations') or []
    if not operations:
        raise ValueError(f"Decision '{decision}' given but no operations were specified.")

    known_names = set(by_name.keys())  # original uploaded files
    known_columns = {name: set(d['columns']) for name, d in by_name.items()}

    for idx, op in enumerate(operations):
        op_type = op.get('type')
        result_name = op.get('result_name') or f'__op{idx}__'

        if op_type == 'append':
            names = op.get('datasets') or []
            if len(names) < 2:
                raise ValueError(f"Operation {idx}: append needs at least two datasets.")
            unknown = [n for n in names if n not in known_names]
            if unknown:
                raise ValueError(f"Operation {idx}: append references unknown dataset(s): {', '.join(unknown)}.")

            known_col_sets = [known_columns[n] for n in names if n in known_columns]
            if len(known_col_sets) == len(names):
                base = known_col_sets[0]
                for cols in known_col_sets[1:]:
                    overlap = len(base & cols) / max(len(base | cols), 1)
                    if overlap < 0.6:
                        raise ValueError(
                            f"Operation {idx}: append rejected -- datasets share only "
                            f"{round(overlap * 100)}% of columns, below the 60% safety threshold."
                        )
                    if overlap < 0.9:
                        validation_warnings.append(
                            f"Operation {idx}: datasets share {round(overlap * 100)}% of columns -- "
                            f"appending with column mismatches; non-shared columns will contain nulls."
                        )
                known_columns[result_name] = set.union(*known_col_sets)
            else:
                # Some inputs are chained results from earlier operations -- their
                # columns aren't known until Build Analytical Dataset actually runs.
                validation_warnings.append(
                    f"Operation {idx}: one or more append inputs are chained operation results -- "
                    f"column overlap will only be confirmed when the dataset is built."
                )

            known_names.add(result_name)

        elif op_type == 'join':
            left_name = op.get('left')
            right_name = op.get('right')
            keys = op.get('keys') or []

            if not left_name or not right_name or not keys:
                raise ValueError(f"Operation {idx}: join needs left, right, and keys all specified.")
            if left_name not in known_names or right_name not in known_names:
                raise ValueError(
                    f"Operation {idx}: join references a dataset that was not found: "
                    f"'{left_name}' or '{right_name}'."
                )

            if left_name in known_columns and right_name in known_columns:
                missing_keys = [
                    k for k in keys
                    if k not in known_columns[left_name] or k not in known_columns[right_name]
                ]
                if missing_keys:
                    raise ValueError(
                        f"Operation {idx}: join key(s) not present in both datasets: {', '.join(missing_keys)}."
                    )
                known_columns[result_name] = known_columns[left_name] | known_columns[right_name]
            else:
                validation_warnings.append(
                    f"Operation {idx}: join involves a chained operation result -- join keys will only "
                    f"be confirmed when the dataset is built."
                )

            if right_name in by_name:
                right_df = pd.DataFrame(by_name[right_name]['records'])
                if not right_df.empty and all(k in right_df.columns for k in keys):
                    dup_key_count = int(right_df.duplicated(subset=keys).sum())
                    if dup_key_count > 0:
                        validation_warnings.append(
                            f"Operation {idx}: join key(s) {keys} are not unique in '{right_name}' "
                            f"({dup_key_count} duplicate key rows) -- this join may fan out rows."
                        )

            known_names.add(result_name)

        else:
            raise ValueError(f"Operation {idx}: unknown operation type '{op_type}'.")
else:
    raise ValueError(f"Unknown planner decision: {decision}")

return [{
    'json': {
        'dataset_session_id': payload['dataset_session_id'],
        'app_session_id': payload.get('app_session_id'),
        'plan': plan,
        'cleaned_datasets': cleaned_datasets,
        'quality_stats': payload['quality_stats'],
        'quality_warnings': payload['quality_warnings'] + validation_warnings
    }
}]

import pandas as pd

item = _items[0]
payload = item['json']
plan = payload['plan']
decision = plan.get('decision', 'standalone')
cleaned_datasets = payload['cleaned_datasets']
by_name = {d['file_name']: d for d in cleaned_datasets}

working = {name: pd.DataFrame(d['records']) for name, d in by_name.items()}
build_notes = []

# Merge role maps from every source file so downstream stats can look up
# each final column's classification (date/currency/number/etc.) without
# re-guessing it. Columns produced purely by a join/append operation that
# don't trace back to an original file simply won't have an entry, and are
# treated as 'text' downstream.
role_map = {}
for d in cleaned_datasets:
    role_map.update(d['role_map'])

if decision == 'standalone':
    source = cleaned_datasets[0]
    final_df = working[source['file_name']]
    build_notes.append(f"Standalone dataset '{source['file_name']}'.")

elif decision in ('append', 'join'):
    operations = plan.get('operations') or []
    if not operations:
        raise ValueError(f"Decision '{decision}' given but no operations were specified.")

    result_df = None
    for idx, op in enumerate(operations):
        op_type = op.get('type')
        result_name = op.get('result_name') or f'__op{idx}__'

        if op_type == 'append':
            names = op.get('datasets') or []
            frames = [working[n] for n in names if n in working]
            if len(frames) < 2:
                raise ValueError(
                    f"Operation {idx}: append needs at least two known datasets, found {len(frames)}."
                )
            result_df = pd.concat(frames, ignore_index=True, sort=False)
            build_notes.append(f"Appended {len(frames)} dataset(s): {', '.join(names)} -> '{result_name}'.")

        elif op_type == 'join':
            left_name = op.get('left')
            right_name = op.get('right')
            keys = op.get('keys') or []
            join_type = op.get('join_type', 'left')

            if left_name not in working or right_name not in working:
                raise ValueError(
                    f"Operation {idx}: join references a dataset that isn't available yet: "
                    f"'{left_name}' or '{right_name}'."
                )

            left_df = working[left_name]
            right_df = working[right_name]
            result_df = left_df.merge(right_df, on=keys, how=join_type, suffixes=('', '_right'))
            build_notes.append(f"Joined '{left_name}' with '{right_name}' on {keys} ({join_type}) -> '{result_name}'.")

        else:
            raise ValueError(f"Operation {idx}: unknown operation type '{op_type}'.")

        working[result_name] = result_df

    final_df = result_df

else:
    raise ValueError(f"Unknown planner decision: {decision}")

records = final_df.to_dict(orient='records')
for row in records:
    for key, value in list(row.items()):
        if pd.isna(value):
            row[key] = None
        else:
            try:
                row[key] = value.isoformat()
            except AttributeError:
                row[key] = str(value) if not isinstance(value, (int, float, bool)) else value

return [{
    'json': {
        'dataset_session_id': payload['dataset_session_id'],
        'app_session_id': payload.get('app_session_id'),
        'plan': plan,
        'build_note': ' | '.join(build_notes),
        'final_rows': int(len(final_df)),
        'final_columns': list(final_df.columns),
        'role_map': role_map,
        'final_records': records,
        'quality_stats': payload['quality_stats'],
        'quality_warnings': payload['quality_warnings']
    }
}]

