const report = $input.item.json;

// TODO: business_id must come from real tenant resolution (Supabase Auth
// bearer token verification), not a hardcoded placeholder. Wire this up
// once the trusted-tenant-resolution pattern is ported into this workflow.
return [{
  json: {
    dataset_session_id: report.dataset_session_id,
    app_session_id: report.app_session_id,
    business_id: 'BUSINESS_ID_PLACEHOLDER',
    final_columns: report.final_columns,
    role_map: report.role_map,
    final_records: report.final_records,
    quality_report: report.quality_report,
    build_note: report.build_note
  }
}];

const saved = $input.item.json;
const previousSessionId = saved.previous_session_id || null;

const meta = { ...saved.meta, previous_session_id: previousSessionId };
const activeDir = saved.active_dir;

return [{
  json: {
    business_id: saved.business_id,
    dataset_session_id: saved.dataset_session_id,
    app_session_id: meta.app_session_id,
    previous_session_id: previousSessionId,
    row_count: saved.row_count,
    csv_text: saved.csv_text,
    meta: meta,
    active_dir: activeDir,
    dataset_path: `${activeDir}/dataset.csv`,
    meta_path: `${activeDir}/meta.json`
  }
}];

const payload = $input.item.json;

// Push the cleaned dataset + its structure straight through -- Workflow 2
// no longer needs to read dataset.csv / meta.json back off disk on a
// live handoff from Workflow 1. dataset_path/meta_path are still passed
// along too, since the files genuinely exist on disk now (written
// directly by Python — Write Session Files to Disk) and Workflow 2's
// standalone question-mode calls, which aren't chained off a Workflow 1
// run, still need a path to read from.
return [{
  json: {
    mode: 'initial_eda',
    dataset_session_id: payload.dataset_session_id,
    business_id: payload.business_id,
    app_session_id: payload.app_session_id,
    dataset_path: payload.dataset_path,
    meta_path: payload.meta_path,
    csv_text: payload.csv_text,
    meta: payload.meta,
    question: null
  }
}];
